function numWord(n, l){
  const W = NUMW[l];
  if (n === 100) return W.h;
  if (n < 10) return W.u[n];
  if (l !== 'kk' && n < 20) return W.teen[n-10];
  const t = Math.floor(n/10), u = n%10;
  if (!u) return W.t[t];
  return W.t[t] + (l === 'en' ? '-' : ' ') + W.u[u];
}

